#include <vector>
#include <unordered_set>
#include <algorithm>

class Solution {
public:
    int maxWallsDestroyed(std::vector<int>& robots, std::vector<int>& walls, int bulletRange) {
        std::sort(walls.begin(), walls.end());
        std::sort(robots.begin(), robots.end());
        std::unordered_set<int> destroyed;

        for (int r : robots) {
            std::vector<int> left_w, right_w;
            for (int w : walls) {
                if (w >= r - bulletRange && w <= r) left_w.push_back(w);
                if (w >= r && w <= r + bulletRange) right_w.push_back(w);
            }
            int new_left = 0, new_right = 0;
            for (int w : left_w) if (!destroyed.count(w)) new_left++;
            for (int w : right_w) if (!destroyed.count(w)) new_right++;

            if (new_left >= new_right) {
                for (int w : left_w) destroyed.insert(w);
            } else {
                for (int w : right_w) destroyed.insert(w);
            }
        }
        return destroyed.size();
    }
};

import java.util.*;

class Solution {
    public int maxWallsDestroyed(int[] robots, int[] walls, int bulletRange) {
        Arrays.sort(walls);
        Arrays.sort(robots);
        Set<Integer> destroyed = new HashSet<>();

        for (int r : robots) {
            List<Integer> leftW = new ArrayList<>();
            List<Integer> rightW = new ArrayList<>();
            for (int w : walls) {
                if (w >= r - bulletRange && w <= r) leftW.add(w);
                if (w >= r && w <= r + bulletRange) rightW.add(w);
            }
            int newLeft = 0, newRight = 0;
            for (int w : leftW) if (!destroyed.contains(w)) newLeft++;
            for (int w : rightW) if (!destroyed.contains(w)) newRight++;

            if (newLeft >= newRight) {
                destroyed.addAll(leftW);
            } else {
                destroyed.addAll(rightW);
            }
        }
        return destroyed.size();
    }
}

var maxWallsDestroyed = function(robots, walls, bulletRange) {
    walls.sort((a, b) => a - b);
    robots.sort((a, b) => a - b);
    const destroyed = new Set();

    for (const r of robots) {
        const leftW = walls.filter(w => w >= r - bulletRange && w <= r);
        const rightW = walls.filter(w => w >= r && w <= r + bulletRange);

        let newLeft = 0, newRight = 0;
        for (const w of leftW) if (!destroyed.has(w)) newLeft++;
        for (const w of rightW) if (!destroyed.has(w)) newRight++;

        if (newLeft >= newRight) {
            for (const w of leftW) destroyed.add(w);
        } else {
            for (const w of rightW) destroyed.add(w);
        }
    }
    return destroyed.size;
